var e={"setup.title":`Harness Maxxing へようこそ`,"setup.subtitle":`このコントロールルームを保護するパスワードを設定してください。`,"setup.token":`セットアップトークン`,"setup.tokenHint":"インストーラーが表示したものです。もう一度確認するには、サーバーで `maxxing setup-link` を実行してください。","setup.tokenRequired":`セットアップトークンが必要です。`,"setup.badToken":"このセットアップリンクは無効、期限切れ（有効期間は 1 時間）、または使用済みです。サーバーで `maxxing setup-link` を実行して新しいリンクを取得してください。","setup.newLink":`サーバーで新しいリンクを発行します：`,"setup.submit":`パスワードを作成`,"setup.footer":`この手順を完了できるのはあなただけです。使い捨てトークンが必要です。`,"login.title":`サインイン`,"login.subtitle":`Harness Maxxing のパスワードを入力してください。`,"login.password":`パスワード`,"login.required":`パスワードを入力してください。`,"login.bad":`パスワードが正しくありません。`,"login.throttled":`試行回数が多すぎます。しばらく待ってからもう一度お試しください。`,"login.submit":`サインイン`,"login.forgot":`パスワードをお忘れですか？`,"login.forgotHelp":`サーバーのターミナルからリセットしてください：`,"pw.new":`新しいパスワード`,"pw.confirm":`パスワードの確認`,"pw.hint":`12文字以上。長いパスフレーズがおすすめです。`,"pw.tooShort":`12文字以上にしてください。`,"pw.mismatch":`パスワードが一致しません。`,"pw.strength.0":`未入力`,"pw.strength.1":`弱すぎます`,"pw.strength.2":`普通`,"pw.strength.3":`良い`,"pw.strength.4":`強力`,"onb.title":`はじめに`,"onb.progress":`セットアップの進行状況`,"onb.stepOf":`ステップ {n}／{total}`,"onb.optional":`任意`,"onb.skip":`今はスキップ`,"onb.step.language":`言語とタイムゾーン`,"onb.step.claude":`Claudeに接続`,"onb.step.workspace":`プロジェクト`,"onb.step.telegram":`Telegram`,"onb.step.backup":`メモリのバックアップ`,"onb.step.done":`完了`,"onb.language.title":`言語とタイムゾーン`,"onb.language.desc":`インターフェース、日付、定期ジョブのスケジュールに使われます。`,"onb.claude.title":`Claudeに接続`,"onb.claude.desc":`Harness Maxxing は、このサーバー上の公式 Claude Code CLI を、あなた自身のアカウントまたは API キーで操作します。他の誰とも共有されません。`,"onb.claude.defaults":`デフォルト`,"onb.claude.defaultsDesc":`新しいセッションで使うモデルと権限です。後からセッションごとに変更できます。`,"onb.claude.later":`後で接続`,"onb.workspace.title":`最初のプロジェクトを選択`,"onb.workspace.desc":`お仕事の種類に合わせたすぐに使えるプロジェクトです。トピックは仕事内容をすでに把握しており、いくつか質問をします。すべてインストールする、選ぶ、スキップする、のいずれも可能です。後から 設定 -> テンプレート で追加できます。`,"onb.workspace.created":`プロジェクトとトピックを作成しました`,"onb.telegram.title":`TelegramからHarnessに話しかける`,"onb.telegram.desc":`あなた専用のボットで、開いているセッションごとにスレッドが作られます。ブラウザと同じ会話をスマートフォンで続けられます。メインチャットに書き込むと新しい会話を始められます。定期ジョブのレポートやサインインの通知もここに届きます。`,"onb.backup.title":`メモリをバックアップ`,"onb.backup.desc":`毎晩、CLAUDE.md、メモリファイル、タスク、定期ジョブがプライベートな GitHub リポジトリにプッシュされます。`,"onb.done.title":`準備完了です`,"onb.done.desc":`現在の設定内容です。すべて後から設定で変更できます。`,"onb.done.finish":`セッションを開く`,"onb.summary.password":`パスワード`,"onb.summary.claude":`Claudeへの接続`,"onb.summary.workspace":`最初のプロジェクト`,"onb.summary.telegram":`Telegram`,"onb.summary.backup":`メモリのバックアップ`,"onb.summary.skipped":`スキップ`,"onb.summary.todo":`未設定`,"onb.tour.sessions":`トピックごとに複数の永続的な会話をライブで表示し、モデルとコストも確認できます。`,"onb.tour.files":`ワークスペースのあらゆるファイルを閲覧、プレビュー、編集できます。`,"onb.tour.tasks":`Harness も読み取り・更新できるカンバンです。`,"onb.tour.crons":`シェルコマンドや Harness のプロンプトをレポート付きでスケジュールできます。`,"onb.tour.telegram":`どの会話もスマートフォンから続けられます。`,"onb.tour.docs":`ガイド、トラブルシューティング、拡張機能の作り方。`,"onb.tour.features":`必要に応じてオンにできる任意のページ：タスク、エージェント、メール、Git、インフラ、チーム。`,"onb.step.profile":`あなたについて`,"onb.profile.title":`自己紹介（任意）`,"onb.profile.desc":`Harness Maxxing は無料で、アカウントは不要です。よろしければ、あなたのことを教えてください。このページの項目はすべて任意です。`,"onb.profile.pseudoDesc":`Harness Maxxing でのニックネームです（Telegram に送られるメッセージのコピーに表示されます）。設定 → プロフィールで変更できます。`,"onb.profile.counterOn":`api.harness-maxxing.com に送信されます。ニックネームと言語はメールアドレスと一緒にのみ送られます。匿名カウンター（バージョン、システム、ヘルスコード。名前や IP は含まれません）は初期設定でオンです。設定 → プロフィールでオフにできます。`,"twofa.title":`Telegramで承認してください`,"twofa.subtitle":`2段階サインインが有効です。このブラウザーにはあなたの承認が必要です。`,"twofa.check":`Telegramを確認してください`,"twofa.checkDesc":`サインインのリクエストをボットのアラートのスレッドに送信しました。「許可」を押すか、下のメッセージのコードを入力してください。`,"twofa.waiting":`承認をお待ちしています… {time}`,"twofa.code":`メッセージのコード`,"twofa.codeLength":`コードは6桁です。`,"twofa.badCode":`コードが正しくありません。`,"twofa.codesPaused":`このサーバーでコードの誤入力が多すぎます。Telegramの「許可」ボタンを使うか、1時間後にもう一度コードを試してください。`,"twofa.verify":`確認`,"twofa.trust":`このブラウザーを30日間信頼する`,"twofa.denied":`Telegramでサインインが拒否されました。`,"twofa.expired":`リクエストの有効期限が切れました。もう一度サインインしてください。`,"twofa.noAnswer":`Telegramが応答しませんか？`,"twofa.noAnswerHelp":`サーバーのターミナルから2段階サインインをオフにし、パスワードでサインインしてください：`,"twofa.setting":`2段階サインイン`,"twofa.settingDesc":`パスワードの後、新しいブラウザーはTelegramでの承認（「許可」ボタンまたはコード）を待ちます。UIを使わずに解除するには、サーバーで maxxing 2fa off を実行します。`,"twofa.forget":`信頼済みブラウザーを削除`,"twofa.forgotten":`他のすべてのブラウザーで再度承認が必要になります。`,"twofa.enableTitle":`2段階サインインをオンにする`,"twofa.enableDesc":`Telegramに送信されたリクエストを承認してください。サインインを保護する前に、ボットが応答することを確認します。`,"twofa.offTitle":`2段階サインインをオフにする`,"twofa.offDesc":`現在のパスワードを入力してください。Telegramに警告が送信されます。`,"twofa.offConfirm":`オフにする`,"twofa.enabled":`2段階サインインはオンです。`,"twofa.needTelegram":`2段階サインインでは、パスワードの後にTelegramでの承認が必要です。先にTelegramボットを連携してください。`,"twofa.linkTelegram":`設定 → Telegram`,"twofa.appCode":`認証アプリのコード`,"twofa.appHint":`認証アプリのコードまたはリカバリーコードも使えます。`,"twofa.recHint":`リカバリーコードも使えます。`,"twofa.noCode":`コードが手元にありませんか？`,"onb.workspace.own":`または独自のプロジェクトを作成`,"onb.step.import":`インポート`,"onb.import.title":`他のエージェントからお越しですか？`,"onb.import.desc":`現在のエージェントが知っているすべて（プロジェクト、トピック、メモリ、スキル）を2分で引き継げます。スキップして最初から始めることもできます。`,"onb.import.skip":`最初から始める`,"onb.step.features":`ページ`,"onb.features.title":`何を使いますか？`,"onb.features.desc":`セッション、ファイル、通知は常に表示されます。今必要なその他のページをオンにしてください。設定 -> 機能からいつでも変更できます。`,"onb.done.notify":`セッション終了時に知らせる`,"onb.done.notifyDesc":`Claude の処理が終わり、このタブが前面にないときに、ブラウザ通知を表示します。`};export{e as default};